"""Rebuild the six static pages after updating content.json. Standard library only."""
from pathlib import Path
import json
from html import escape as esc

ROOT = Path(__file__).resolve().parent.parent
ARTS = json.loads((ROOT / 'content.json').read_text(encoding='utf-8'))['arts']
COLORS = {'shezhi': ('#eee5db', '#9b604b'), 'zhubian': ('#e5ead8', '#60794c'), 'sunkehua': ('#efe5cf', '#9c793e'), 'shexiang': ('#e9e6dd', '#847359')}

def icon(name):
    paths = {'arrow': '<path d="M4 12h15M13 5l7 7-7 7"/>', 'qr':'<path d="M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h2v2h-2zM20 14v7h-5M12 3v3M3 12h6M12 10v5M12 20v1"/>', 'bookmark':'<path d="M6 3h12v18l-6-4-6 4z"/>', 'share':'<path d="M12 16V3m-4 4 4-4 4 4M5 11v10h14V11"/>'}
    return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">{paths[name]}</svg>'

def head(title, description, prefix=''):
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f7f5ec"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:type" content="website"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}styles.css?v=20261029-2"><script defer src="{prefix}assets/vendor/qrcode.js"></script><script defer src="{prefix}app.js"></script></head>'''

def header(prefix=''):
    return f'''<a class="skip" href="#main">跳到正文</a><header class="site-header"><div class="wrap nav-inner"><a class="brand" href="{prefix}index.html" aria-label="章村四艺首页"><span class="brand-mark" aria-hidden="true">章<br>村</span><span><span class="brand-name">章村四艺</span><span class="brand-en">ZHANGCUN · FOUR ARTS</span></span></a><button class="nav-toggle" aria-expanded="false" aria-controls="main-nav">菜单 ＋</button><nav class="nav-links" id="main-nav" aria-label="主导航"><a href="{prefix}index.html#arts">四艺故事</a><a href="{prefix}index.html#zhangcun">来自章村</a><a href="{prefix}index.html#collection">我的故事册</a><a class="nav-qr" href="{prefix}qrcodes.html">{icon('qr')}故事二维码</a></nav></div></header>'''

def footer(prefix=''):
    return f'''<footer class="site-footer"><div class="wrap"><div class="footer-top"><a class="brand" href="{prefix}index.html"><span class="brand-mark" aria-hidden="true">章<br>村</span><span><span class="brand-name">章村四艺</span><span class="brand-en">一物一故事 · 把手艺带进日常</span></span></a><div class="footer-links"><a href="{prefix}index.html#arts">读四艺故事</a><a href="{prefix}qrcodes.html">制作故事二维码</a></div></div><div class="footer-bottom"><p>北京航空航天大学章村四艺团队</p><span>浙江 · 安吉 · 章村</span></div></div></footer><div class="toast" id="toast" role="status" aria-live="polite"></div><noscript><p class="noscript-note">故事正文可直接阅读；收藏与二维码功能需要开启 JavaScript。</p></noscript></body></html>'''

def style(art):
    tint, accent = COLORS[art['id']]
    return f'--tint:{tint};--accent:{accent}'

def home():
    people = ''.join(f'''<a class="hero-person" href="stories/{a['id']}.html" aria-label="跟{a['character']}读{a['name']}故事"><img src="assets/{a['id']}-ip.png" alt="{a['name']} IP {a['character']}" width="820" height="820"><span class="person-label"><b>{a['character']}</b>{a['name']}</span></a>''' for a in ARTS)
    cards = ''.join(f'''<a class="art-card" style="{style(a)}" href="stories/{a['id']}.html"><span class="card-no">0{i+1} / {esc(a['en'])}</span><h3>{a['name']}</h3><div class="card-caption">{esc(a['tagline'])}</div><img class="card-ip" loading="lazy" src="assets/{a['id']}-ip.png" width="820" height="820" alt="{a['character']}，{a['name']}故事的引导角色"><div class="card-bottom"><span>跟着{a['character']} · 读故事</span><span class="arrow" aria-hidden="true">↗</span></div></a>''' for i,a in enumerate(ARTS))
    stamps = ''.join(f'''<a class="stamp" data-stamp="{a['id']}" href="stories/{a['id']}.html" aria-label="{a['name']}故事，前往阅读"><img loading="lazy" src="assets/{a['id']}-ip.png" width="820" height="820" alt=""><span>{a['name']}</span></a>''' for a in ARTS)
    body = f'''<body>{header()}<main id="main"><div class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow">浙江 · 安吉 · 章村 / 手艺里的乡土</div><h1>山野有艺，<br><em>日常有故事。</em></h1><p class="hero-description">一缕彩线，一片竹篾，一张笋壳，一段草木香。<br>跟着四位山乡伙伴，打开文创背后的手艺故事，<br>把章村的记忆，带进你的日常。</p><div class="hero-actions"><a class="button" href="#arts">翻开四艺故事 {icon('arrow')}</a><a class="text-link" href="#zhangcun">认识章村 <span aria-hidden="true">↗</span></a></div><p class="hero-note">一物一码 · 扫码读故事 · 让手艺与生活相遇</p></div><div class="hero-art"><div class="hero-orbit"></div><img class="hero-lower" src="assets/village.png" alt="" width="1000" height="667">{people}<span class="hero-seal" aria-hidden="true">四艺相逢</span></div></section><div class="intro-strip"><span><strong>一件文创</strong> · 一段与章村的相遇</span><span>畲织 / 竹编 / 笋壳画 / 畲香</span><span>从手心的小物，读懂山乡的故事 <span aria-hidden="true">↓</span></span></div><section class="section" id="arts"><div class="section-head"><div><div class="eyebrow">Four arts, four stories</div><h2>四门手艺，四种相遇。</h2></div><p class="section-intro">点开一张故事卡，认识材料，也认识手艺。<br>如果你手里已有文创，扫描产品上的二维码就能直达。</p></div><div class="arts-grid">{cards}</div></section></div><section class="section origin-section" id="zhangcun"><div class="wrap origin-grid"><div class="origin-photo"><img loading="lazy" src="assets/zhubian-craft.webp" width="948" height="991" alt="竹编手作教学中，两人共同查看竹篾的编织细节"><p class="photo-caption">竹编传习 · 项目资料图片</p></div><div class="origin-copy"><div class="eyebrow">From the mountains of Anji</div><h2>故事从章村出发，<br>在一双手里延续。</h2><div class="origin-quote">「手艺，是人与山野的对话。」</div><p>章村在浙江安吉。这里的畲乡文化、竹乡生活，为“章村四艺”提供了创作的起点。从郎村的畲族彩带，到日常可见的竹编器物，材料经过双手，留下生活的印记。</p><p>我们把畲织、竹编、笋壳画与畲香编成四篇小小的故事。用年轻的 IP 形象讲述手艺，让一次购买、一次赠礼，也成为重新认识乡土的机会。</p><div class="origin-tags"><span>在地文化</span><span>乡土材料</span><span>手作温度</span><span>文创新意</span></div></div></div></section><section class="section" id="collection"><div class="wrap collection-shell"><div class="collection-copy"><div class="eyebrow">My little storybook</div><h2>把四艺，收进故事册。</h2><p>读完故事，点击“收入我的故事册”，就能点亮一位伙伴。让下一次相遇，从记住一门手艺开始。</p><div class="collection-progress">已收藏 <strong id="collection-count">0 / 4</strong> 段故事 · 保存在当前浏览器</div></div><div class="stamps">{stamps}</div></div></section></main>{footer()}'''
    (ROOT/'index.html').write_text(head('章村四艺｜山野有艺，日常有故事', '跟着阿畲、竹仔、笋壳妹和香香，读懂畲织、竹编、笋壳画与畲香的文创故事。')+body,encoding='utf-8')

def story(art, i):
    prefix='../'; aid=art['id']; following=ARTS[(i+1)%len(ARTS)]
    paragraphs=''.join(f'<p class="story-paragraph">{esc(p)}</p>' for p in art['paragraphs'])
    steps=''.join(f'<div class="step"><span class="step-no">0{j+1}</span><div><h3>{esc(s["title"])}</h3><p>{esc(s["text"])}</p></div></div>' for j,s in enumerate(art['steps']))
    sources=''.join(f'<li><a href="{esc(s["url"])}" target="_blank" rel="noopener noreferrer">{esc(s["title"])}</a></li>' for s in art['sources'])
    title='<br>'.join(esc(x) for x in art['titleLines'])
    caption='工坊设计示意 · 章村四艺项目方案'
    imagefile=f'{aid}-workshop.webp'
    if aid=='sunkehua': imagefile='sunkehua-craft.webp';caption='笋壳画展陈 · 项目资料图片'
    html=f'''<body data-story="{aid}" style="{style(art)}">{header(prefix)}<div class="story-progress" aria-hidden="true"></div><main id="main"><div class="wrap"><div class="breadcrumb"><a href="../index.html">首页</a><span>/</span><a href="../index.html#arts">四艺故事</a><span>/</span>{art['name']}</div><section class="story-hero"><div><div class="eyebrow">故事 0{i+1} / {art['name']} · {esc(art['en'])}</div><h1>{title}</h1><p class="intro">{esc(art['intro'])}</p><div class="story-meta"><span>{art['character']}的故事卡</span><span>约 2 分钟阅读</span><span>文创里的章村</span></div></div><div class="story-portrait"><span class="portrait-word" aria-hidden="true">{art['name']}</span><img src="../assets/{aid}-ip.png" width="820" height="820" alt="{art['name']}项目 IP {art['character']}"><div class="portrait-label"><b>你好，我是{art['character']}</b><span>0{i+1} / 04</span></div></div></section><nav class="story-tabs" aria-label="本页章节"><a href="#story">读一段故事</a><a href="#craft">看一门手艺</a><a href="#keepsake">留一份记忆</a></nav><section class="reading-layout" id="story"><aside class="reading-aside"><div class="aside-label">THE STORY</div><p>{esc(art['tagline'])}</p><img src="../assets/{aid}-ip.png" width="820" height="820" alt="" loading="lazy"></aside><article class="reading-content"><h2>小物背后，是生活。</h2>{paragraphs}<div class="fact-box"><h3>再靠近一点 · 手艺小知识</h3><p>{esc(art['fact'])}</p></div></article></section></div><section class="section craft-section" id="craft"><div class="wrap"><div class="craft-head"><div class="eyebrow">The making</div><h2>三个步骤，看懂一门手艺。</h2><p class="section-intro">从认识材料，到完成一件作品。以下为工艺入门概览。</p></div><div class="craft-grid"><figure class="craft-photo"><img src="../assets/{imagefile}" alt="{art['name']}{'作品展示' if aid=='sunkehua' else '工坊空间设计示意'}" loading="lazy" width="1400" height="1050"><figcaption>{caption}</figcaption></figure><div class="steps">{steps}</div></div></div></section><section class="section" id="keepsake"><div class="wrap"><div class="product-panel"><img src="../assets/{aid}-ip.png" alt="" loading="lazy" width="820" height="820"><div><div class="eyebrow">A story to keep</div><h2>{esc(art['productTitle'])}</h2><p>{esc(art['productText'])}</p><div class="product-actions"><button class="button" data-collect="{aid}" aria-pressed="false">{icon('bookmark')}<span>收入我的故事册</span></button><button class="button secondary" data-share>{icon('share')}分享这段故事</button></div></div></div><details class="sources"><summary>关于这张故事卡 · 资料与创作说明</summary><div class="source-body"><p>{esc(art['sourceNote'])}</p><p>IP 形象来自章村四艺 1029 版项目方案；角色台词与文创文案为项目叙事。所列步骤为入门概述，具体作品应以实际材料和制作说明为准。</p><ul>{sources}</ul></div></details></div></section><div class="wrap"><div class="next-story"><div><div class="next-label">再读一门手艺 / NEXT STORY</div><a href="{following['id']}.html"><strong>{following['name']} · {following['character']}</strong> {icon('arrow')}</a></div><a href="{following['id']}.html" aria-label="前往{following['name']}故事"><img src="../assets/{following['id']}-ip.png" width="820" height="820" alt="" loading="lazy"></a></div></div></main><dialog class="share-dialog" id="share-dialog" aria-labelledby="share-title"><button class="dialog-close" aria-label="关闭分享窗口">×</button><h2 id="share-title">把{art['name']}的故事，分享出去。</h2><p>扫码，和{art['character']}再一次相遇。</p><div class="qr-code" id="share-qr"></div><p id="share-address"></p><button class="button" id="copy-story-link">复制故事链接</button></dialog>{footer(prefix)}'''
    (ROOT/'stories'/f'{aid}.html').write_text(head(f'{art["name"]} · {art["character"]}的故事｜章村四艺',art['intro'],prefix)+html,encoding='utf-8')

def qrcodes():
    cards=''.join(f'''<article class="qr-card" style="{style(a)}"><img src="assets/{a['id']}-ip.png" alt="{a['character']}" width="820" height="820"><h2>{a['name']}</h2><div class="qr-tagline">跟着{a['character']}，读懂文创背后的故事</div><div class="qr-code" id="qr-{a['id']}"><p class="qr-placeholder">输入正式网站地址<br>生成故事二维码</p></div><a class="qr-target" id="link-{a['id']}" target="_blank" rel="noopener">等待正式网站地址</a><button class="button" data-download="{a['id']}" data-format="png" disabled>下载 PNG 二维码</button><button class="button secondary" data-download="{a['id']}" data-format="svg" disabled>下载 SVG 印刷版</button><button class="button secondary" data-copy="{a['id']}" disabled>复制故事链接</button></article>''' for a in ARTS)
    html=f'''<body>{header()}<main id="main" class="wrap"><div class="qr-heading"><div class="eyebrow">Scan a little, discover more</div><h1>一物一码，一艺一故事。</h1><p>给文创配一张故事卡。扫描二维码，即可打开对应的四艺故事。<br>可以下载单独的二维码，也可以直接打印整套故事卡。</p></div><form class="qr-form" id="qr-form"><label for="site-address">正式网站根地址</label><div class="qr-input-row"><input type="url" id="site-address" required placeholder="https://你的账号.github.io/仓库名/" autocomplete="url" aria-describedby="qr-status"><button class="button" type="submit">生成四张故事卡 {icon('arrow')}</button></div><p class="form-hint" id="qr-status" role="status">上线后会自动使用当前网址。本地预览请先填写已发布的 HTTPS 地址。</p></form><div class="qr-grid">{cards}</div><div class="print-row"><button class="button" id="print-cards" disabled>打印四张故事卡</button><a class="button secondary" href="index.html#arts">返回四艺故事</a></div><p class="qr-footnote">二维码直接链接到故事页，生成过程在你的浏览器内完成。印刷时请保留二维码四周白边；先打样扫码，再批量制作。网址保持不变，故事内容就可以持续更新。此页不验证所填网址是否已上线，请在手机上打开并确认。</p></main>{footer()}'''
    (ROOT/'qrcodes.html').write_text(head('故事二维码｜章村四艺','为畲织、竹编、笋壳画和畲香制作独立故事二维码，支持 PNG、SVG 下载及整套故事卡打印。')+html,encoding='utf-8')

home()
for i,art in enumerate(ARTS): story(art,i)
qrcodes()
print('Built homepage, four stories, and QR card page.')
